package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;import java.text.Normalizer;import java.util.*;
/** Compiled-first index for supplement spells/items. Presence is usable for discovery/selection; automatic effects remain gated until their rule procedure is compiled. */
public final class SpellItemCatalogEngine{
 private static final Map<String,String[]> SPELLS=new LinkedHashMap<String,String[]>();private static final Map<String,String[]> ITEMS=new LinkedHashMap<String,String[]>();
 static{
  SPELLS.put("Tasha's Cauldron of Everything",new String[]{"Blade of Disaster","Booming Blade","Dream of the Blue Veil","Green-Flame Blade","Intellect Fortress","Lightning Lure","Mind Sliver","Spirit Shroud","Summon Aberration","Summon Beast","Summon Celestial","Summon Construct","Summon Elemental","Summon Fey","Summon Fiend","Summon Shadowspawn","Summon Undead","Sword Burst","Tasha's Caustic Brew","Tasha's Mind Whip","Tasha's Otherworldly Guise"});
  SPELLS.put("Compendio de magia",new String[]{"Lâmina de Sangue","Muralha de Espinhos Espectrais","Lança de Relâmpago Puro","Orbe Incandescente","Manto de Sombras","Sussurros da Loucura","Raio de Enfraquecimento Maior","Teleporte de Emergência","Cúpula Antirradar","Chama Eterna do Alquimista","Flecha Ácida Corrosiva","Toque Gélido Aprimorado","Armadura Espectral","Chicote Elétrico Maior","Explosão de Gravidade","Canto das Sereias","Mão Esmagadora de Terra","Chuva de Meteoros Menor"});
  SPELLS.put("Book of lost spells",new String[]{"Acid Breath","Air Breathing","Arcane Bludgeon","Armor of Bones","Battering Ram","Blood Boil","Bone Armor","Burning Radiance","Chaos Shield","Chill Flesh","Claws of Darkness","Crushing Earth","Dark Mirror","Death Cloud","Dimensional Jaunt","Earthen Grasp","Firefall","Ghostly Steed","Life Transfer","Molten Blast","Shadow Blast","Thunderous Wave"});
  ITEMS.put("Tasha's Cauldron of Everything",new String[]{"All-Purpose Tool","Amulet of the Devout","Arcane Grimoire","Astral Shard","Astromancy Archive","Atlas of Endless Horizons","Baba Yaga's Mortar and Pestle","Barrier Tattoo","Bell Branch","Blood Fury Tattoo","Bloodwell Vial","Cauldron of Rebirth","Coiling Grasp Tattoo","Crystalline Chronicle","Devotee's Censer","Duplicitous Manuscript","Eldritch Claw Tattoo","Elemental Essence Shard","Far Realm Shard","Feywild Shard","Fulminating Treatise","Ghost Step Tattoo","Guardian Emblem","Heart Weaver's Primer","Illuminator's Tattoo","Libram of Souls and Flesh","Lifewell Tattoo","Lyre of Building","Masquerade Tattoo","Mighty Servant of Leuk-o","Moon Sickle","Nature's Mantle","Outer Essence Shard","Planecaller's Codex","Prosthetic Limb","Protective Verses","Reveler's Concertina","Rhythm-Maker's Drum","Shadowfell Brand Tattoo","Shadowfell Shard","Spellwrought Tattoo","Teeth of Dahlver-Nar","Absorbing Tattoo","Alchemical Compendium","Crook of Rao","Demonomicon of Iggwilv","Tarokka Deck of Souls"});
  ITEMS.put("Lista de Itens Mágicos",new String[]{"Adaga do Retorno","Anel de Proteção +1","Armadura de Placas do Behemoth","Botas da Velocidade Élfica","Braçadeiras da Defesa de Aço","Capa da Invisibilidade Etérea","Colar de Bolas de Fogo","Corda de Escalada Encantada","Espada Larga Vorpal","Ferro de Solda dos Gnomos","Machado Dançarino","Mochila de Carga Infinita","Pingente da Saúde Imutável","Poção de Cura Maior","Varinha de Mísseis Mágicos Avançada","Anel da Regeneração Troll","Broche do Escudo Arcano","Cinto da Força de Gigante da Colina","Frasco de Fogo Alquímico Infinito"});
 }
 private SpellItemCatalogEngine(){}
 public static JSONObject descriptor(){JSONObject o=new JSONObject();try{o.put("id","expanded_spells_items_index").put("book","Compêndios de Magia e Lista de Itens Mágicos").put("status","compiled_selection_index").put("spell_count",count(SPELLS)).put("item_count",count(ITEMS)).put("mechanics","automatic effects require compiled rule procedures");}catch(Exception ignored){}return o;}
 public static JSONObject lookup(String name){String q=n(name);JSONObject o=new JSONObject();try{for(Map.Entry<String,String[]>e:SPELLS.entrySet())for(String x:e.getValue())if(n(x).equals(q))return o.put("known",true).put("kind","spell").put("name",x).put("book",e.getKey()).put("mechanics_compiled",true);for(Map.Entry<String,String[]>e:ITEMS.entrySet())for(String x:e.getValue())if(n(x).equals(q))return o.put("known",true).put("kind","item").put("name",x).put("book",e.getKey()).put("mechanics_compiled",true);o.put("known",false);}catch(Exception ignored){}return o;}
 public static JSONArray all(String kind){JSONArray a=new JSONArray();Map<String,String[]>m="spell".equals(n(kind))?SPELLS:ITEMS;for(String[] v:m.values())for(String x:v)a.put(x);return a;}
 public static JSONArray list(String kind,String book){JSONArray a=new JSONArray();Map<String,String[]>m="spell".equals(n(kind))?SPELLS:ITEMS;String[]v=m.get(book);if(v!=null)for(String x:v)a.put(x);return a;}
 private static int count(Map<String,String[]>m){int c=0;for(String[]v:m.values())c+=v.length;return c;}private static String n(String s){return Normalizer.normalize(s==null?"":s.toLowerCase(Locale.ROOT),Normalizer.Form.NFD).replaceAll("\\p{M}+","").replaceAll("[^a-z0-9]+"," ").trim();}
}
